import DDBStickerBrowser from "../../apps/DDBStickerBrowser";
import { PatreonHelper, utils } from "../../lib/_module";
export function addStickerBrowserControl(controls) {
    if (!game.user?.isGM)
        return;
    const tier = PatreonHelper.getPatreonTier();
    const tiers = PatreonHelper.calculateAccessMatrix(tier);
    const devMode = utils.getSetting("developer-mode");
    if (!devMode && !tiers.experimentalMid)
        return;
    controls.tiles.tools["ddb-stickers"] = {
        name: "ddb-stickers",
        order: 99,
        title: "DDB Sticker Browser",
        icon: "fa-solid fa-shapes",
        button: true,
        visible: true,
        onChange: (_event, active) => {
            if (active === false)
                return;
            new DDBStickerBrowser().render({ force: true });
        },
    };
}
